        sql = f"\n        SELECT COUNT(*)\n            FROM demo_schema.surveys\n            WHERE DATE(TO_TIMESTAMP(created_at) AT TIME ZONE 'America/Sao_Paulo') <= DATE_TRUNC('day', CURRENT_DATE - INTERVAL '1 day')\n        "
